'use strict';
let missionRegistry=null;
function mission(id){return missionRegistry?.missions.find(m=>m.id===id);}
function missionTeaser(id){const m=mission(id);return m?`<div class="mission-teaser" data-mission-teaser="${esc(id)}"><span>Mission</span><p>${esc(m.headline)}</p><a class="text-link" href="#mission/${esc(id)}">Mục tiêu · Phương pháp · Ứng dụng${icon('arrow')}</a></div>`:'';}
function missionSources(m){return `<details class="mission-sources"><summary>${m.sources.length} nguồn đối chiếu · ${esc(missionRegistry.review_date)}</summary><ul>${m.sources.map(s=>`<li><strong>${esc(s.relative_display_path)}</strong><span>Dòng ${s.line_start}–${s.line_end} · SHA256 ${esc(s.sha256.slice(0,16))}…</span><p>${esc(s.claim_scope)}</p></li>`).join('')}</ul><p class="muted">Tên hồ sơ, đoạn nguồn và hash để đối chiếu. Đây không phải liên kết tới ổ đĩa của máy nguồn.</p></details>`;}
function missionPanel(id){const m=mission(id);if(!m)return '';return `<section class="paper-panel mission-panel" data-mission-panel="${esc(id)}"><header class="mission-panel-head"><div><span class="mission-kicker">Mission · ${esc(project(id)?.name||id)}</span><h2>${esc(m.headline)}</h2></div><a class="text-link" href="#connections/${id==='qrw'?'':esc(id)}">${id==='qrw'?'Xem liên kết 7 module':'Vai trò trong 7 module'}${icon('arrow')}</a></header>${m.owner_definition?`<div class="mission-owner-definition"><strong>Mission do Sơn xác định</strong><p>${esc(m.owner_definition)}</p></div>`:''}<div class="mission-three"><section><span class="mission-question">Mục tiêu nghiên cứu</span><h3>${esc(m.objective.summary)}</h3><ul>${m.objective.points.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section><span class="mission-question">Phương pháp khoa học nghiên cứu</span><h3>${esc(m.method.summary)}</h3><ul>${m.method.points.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section><span class="mission-question">Kết quả thực tế để ứng dụng</span><p class="mission-output-label">Đầu ra hướng tới</p><p>${esc(m.application.target)}</p><p class="mission-output-label">Hiện có theo bằng chứng</p><p>${esc(m.application.current)}</p></section></div><div class="mission-limits"><strong>Điều kiện và giới hạn</strong><ul>${m.application.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>${missionSources(m)}</section>`;}
function missionPage(id){const m=mission(id);if(!m)return empty('Chưa có mission được đối chiếu','Chọn module có trong registry mission.');return `<div class="mission-toolbar"><a class="text-link" href="#missions">${icon('back')}Tất cả mission</a><a class="button secondary" href="#project/${esc(id)}">Mở workspace${icon('arrow')}</a></div>${missionPanel(id)}<div class="notice">Mission mô tả mục tiêu và phương pháp trong hồ sơ nguồn. Kết quả hướng tới không đồng nghĩa đã đạt; trạng thái của snapshot dashboard có thể cũ hơn lần rà soát mission.</div>`;}
function missionsPage(){if(!missionRegistry)return empty('Chưa đọc được mission','Thử làm mới để đọc registry đã đối chiếu.');return `<div class="mission-intro"><div><h2>Tám mission. Một hệ nghiên cứu.</h2><p>Mỗi module có một câu hỏi riêng, phương pháp riêng và đầu ra có thể kiểm tra. QRW cung cấp lớp nền quản trị; bảy module bổ sung vai trò cho nhau.</p></div><a class="button primary" href="#connections">Xem liên kết 7 module${icon('arrow')}</a></div><div class="mission-directory">${missionRegistry.missions.map(m=>{const p=project(m.id);return `<article class="paper-panel mission-summary ${esc(p?.color||'blue')}" data-mission-summary="${esc(m.id)}"><div class="mission-summary-top">${p?projectMark(p):''}<div><h3>${esc(p?.name||m.id)}</h3><span>${m.id==='qrw'?'Nền tảng dùng chung':'Module nghiên cứu / công cụ'}</span></div></div><h4>${esc(m.headline)}</h4><p>${esc(m.objective.summary)}</p><a class="text-link" href="#mission/${esc(m.id)}">Đọc mission đầy đủ${icon('arrow')}</a></article>`;}).join('')}</div><div class="notice">Các mục hiện có được tách khỏi đích ứng dụng. Ngày rà soát mission: ${esc(missionRegistry.review_date)}. Liên kết theo mission là thiết kế đề xuất, không tự thay cấu hình, dữ liệu đầu vào hoặc gate.</div>`;}
const missionNodePositions={stockmonitor:[22,34],fundamentalpanel:[22,185],lunavn:[22,336],rnv3:[322,34],fitechsnm:[322,185],kronos:[322,336],fitechml:[622,185]};
const missionNodeRoles={stockmonitor:'Chú ý thị trường',fundamentalpanel:'Bối cảnh doanh nghiệp',lunavn:'Sàng lọc & hiển thị',fitechsnm:'Nghiên cứu chiến lược',rnv3:'Chuẩn hóa chỉ báo & chiến lược',kronos:'Dự báo lợi suất',fitechml:'Học & kiểm định mô hình'};
function connectionDiagram(selected){const edges=missionRegistry.relationships;return `<div class="connection-diagram"><svg viewBox="0 0 830 470" role="img" aria-label="Liên kết mục tiêu giữa bảy module. Chi tiết và điều kiện từng đường nối nằm ở danh sách bên dưới."><defs><marker id="mission-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z"/></marker></defs>${edges.map(e=>{const [x1,y1]=missionNodePositions[e.from],[x2,y2]=missionNodePositions[e.to];let d;if(e.from==='fitechml'&&e.to==='lunavn')d='M712 249V444H112V400';else if(x1===x2)d=`M${x1+90} ${y1+64}V${y2}`;else if(e.from==='lunavn')d=`M${x1+180} ${y1+32}C${x1+230} ${y1+32} ${x2-50} ${y2+32} ${x2} ${y2+32}`;else d=`M${x1+180} ${y1+32}C${x1+240} ${y1+32} ${x2-60} ${y2+32} ${x2} ${y2+32}`;return `<path class="mission-edge ${!selected||e.from===selected||e.to===selected?'focused':''}" d="${d}" marker-end="url(#mission-arrow)"><title>${esc(project(e.from)?.name)} → ${esc(project(e.to)?.name)}: ${esc(e.purpose)}</title></path>`;}).join('')}${Object.entries(missionNodePositions).map(([id,[x,y]])=>`<a href="#mission/${id}" aria-label="Đọc mission ${esc(project(id)?.name||id)}"><rect class="mission-svg-node ${selected===id?'selected':''}" x="${x}" y="${y}" width="180" height="64" rx="12"/><text class="mission-svg-title" x="${x+15}" y="${y+26}">${esc(project(id)?.name||id)}</text><text class="mission-svg-role" x="${x+15}" y="${y+46}">${missionNodeRoles[id]}</text></a>`).join('')}</svg></div>`;}
function connectionsPage(selected){if(!missionRegistry)return empty('Chưa đọc được mission','Thử làm mới.');if(!(selected in missionNodePositions))selected='';const edges=missionRegistry.relationships.filter(e=>!selected||e.from===selected||e.to===selected);return `<section class="paper-panel connection-map"><div class="section-heading"><div><h2>Liên kết theo mission của 7 module</h2><p>Quan hệ mục tiêu · chưa phải pipeline dữ liệu đã nối</p></div><a class="text-link" href="#missions">Tám mission${icon('arrow')}</a></div><div class="connection-foundation"><a href="#mission/qrw"><strong>QRW Data Foundation</strong><span>Nguồn · Hợp đồng · Phiên bản · Lineage</span></a><p>QRW là lớp nền riêng, không nằm trong bảy node. Không tự mở cutover hoặc thay đầu vào nghiên cứu.</p></div>${connectionDiagram(selected)}<div class="connection-filters" aria-label="Lọc liên kết theo module"><a href="#connections" class="${!selected?'selected':''}">Tất cả</a>${Object.keys(missionNodePositions).map(id=>`<a class="${selected===id?'selected':''}" href="#connections/${id}">${esc(project(id)?.name||id)}</a>`).join('')}</div><p class="mission-graph-note">Mũi tên nét đứt biểu thị quan hệ mục tiêu, chưa phải bằng chứng dữ liệu đã truyền. RN V3 → RN V2 do Sơn xác định; các đường còn lại là đề xuất liên kết theo mission. Nhấn module để đọc mission; chọn bộ lọc để xem trách nhiệm và điều kiện từng đường nối. Không có nghiên cứu, dữ liệu hoặc giao dịch nào được chạy từ sơ đồ này.</p></section><div class="connection-list">${edges.map(e=>`<article class="paper-panel connection-card" data-connection="${esc(e.id)}"><div class="connection-pair"><a href="#mission/${esc(e.from)}">${esc(project(e.from)?.name)}</a>${icon('arrow')}<a href="#mission/${esc(e.to)}">${esc(project(e.to)?.name)}</a></div><h3>${esc(e.purpose)}</h3><p>${esc(e.deliverable)}</p><div class="connection-condition"><strong>Điều kiện trước khi dùng</strong><p>${esc(e.condition)}</p></div><span class="connection-proposed">${e.status==='USER_DEFINED_TARGET_RELATION'?'Hướng mission do Sơn xác định · chưa xác minh bàn giao thực thi':'Đề xuất liên kết theo mission · chưa xác minh thực thi'}</span></article>`).join('')}</div>`;}
function validateMissionRegistry(data){
  const expected=['qrw','kronos','fitechml','fitechsnm','rnv3','stockmonitor','lunavn','fundamentalpanel'];
  const fail=()=>{throw new Error('Mission registry không đúng phạm vi đã đăng ký');};
  const text=x=>typeof x==='string'&&x.trim().length>0;
  if(data?.schema!=='FITECHHUB_MISSIONS_V1'||!Array.isArray(data.missions)||data.missions.length!==8||new Set(data.missions.map(m=>m.id)).size!==8||expected.some(id=>!data.missions.some(m=>m.id===id))||!Array.isArray(data.relationships)||data.relationships.length!==7)fail();
  for(const m of data.missions){if(!text(m.headline)||!['objective','method'].every(k=>text(m[k]?.summary)&&Array.isArray(m[k]?.points)&&m[k].points.length>=2&&m[k].points.every(text))||!text(m.application?.target)||!text(m.application?.current)||!Array.isArray(m.application?.limitations)||!m.application.limitations.every(text)||!Array.isArray(m.sources)||m.sources.length<3||m.sources.some(s=>!text(s.relative_display_path)||!/^[a-f0-9]{64}$/.test(s.sha256)||!Number.isInteger(s.line_start)||!Number.isInteger(s.line_end)||s.line_start<1||s.line_end<s.line_start||s.absolute_path))fail();}
  const edges=data.relationships;
  if(new Set(edges.map(e=>e.id)).size!==edges.length||edges.some(e=>!(e.from in missionNodePositions)||!(e.to in missionNodePositions)||e.from===e.to||!['PROPOSED_MISSION_RELATION','USER_DEFINED_TARGET_RELATION'].includes(e.status)||e.execution_verified!==false||!text(e.purpose)||!text(e.deliverable)||!text(e.condition)))fail();
  const primary=edges.filter(e=>e.status==='USER_DEFINED_TARGET_RELATION');if(primary.length!==1||primary[0].from!=='rnv3'||primary[0].to!=='fitechsnm')fail();
  const seen=new Set(['rnv3']);for(let i=0;i<7;i++)for(const e of edges)if(seen.has(e.from)||seen.has(e.to)){seen.add(e.from);seen.add(e.to);}if(seen.size!==7)fail();
  return data;
}
